import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.CLq81i8L.js";const g=JSON.parse('{"title":"Editor 产品设计文档","description":"","frontmatter":{},"headers":[],"relativePath":"editor/design/index.md","filePath":"editor/design/index.md","lastUpdated":1785288787000}'),i={name:"editor/design/index.md"};function o(s,t,n,l,c,h){return a(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="editor-产品设计文档" tabindex="-1">Editor 产品设计文档 <a class="header-anchor" href="#editor-产品设计文档" aria-label="Permalink to &quot;Editor 产品设计文档&quot;">​</a></h1><blockquote><p>页面线框、交互流、运行时架构 — 基于 <code>editor/src</code> 当前实现</p></blockquote><p>产品能力矩阵见 <a href="./../capabilities.html">../capabilities.md</a>；架构见 <a href="./../architecture.html">../architecture.md</a>。</p><h2 id="文档索引" tabindex="-1">文档索引 <a class="header-anchor" href="#文档索引" aria-label="Permalink to &quot;文档索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>范围</th></tr></thead><tbody><tr><td><a href="./overview.html">信息架构与布局</a></td><td>路由、AppLayout、qiankun 嵌入</td></tr><tr><td><a href="./designer.html">设计器</a></td><td>三栏布局、画布、属性面板、部件库</td></tr><tr><td><a href="./instances-publish.html">实例与发布</a></td><td>列表、保存、发布、预览、嵌入</td></tr><tr><td><a href="./runtime.html">运行时架构</a></td><td>WidgetRenderer、事件引擎、联动、校验</td></tr></tbody></table><h2 id="设计原则" tabindex="-1">设计原则 <a class="header-anchor" href="#设计原则" aria-label="Permalink to &quot;设计原则&quot;">​</a></h2><ol><li><strong>Widget 为原子单元</strong>：85 目录 / 91 注册项；registry + Schema 工厂 + 运行时组件；<code>SchemaType = string</code></li><li><strong>设计/运行分离</strong>：<code>WIDGET_SURFACE_KEY</code> 区分 editor（含 mock）与 runtime</li><li><strong>Store 职责拆分</strong>：<code>widgetStore</code> 数据真源，<code>editorStore</code> 交互 + immer 历史，<code>boardStore</code> 画布，<code>apiStore</code> 持久化（共 12 Store）</li><li><strong>Schema JSON 统一格式</strong>：<code>{ widgets, board: { canvas, variables, events } }</code></li><li><strong>双布局</strong>：<code>free</code> 绝对定位（大屏）/ <code>flex</code> 流式（表单页）</li><li><strong>嵌入友好</strong>：PublishView postMessage + <code>?interaction=</code> 只读/交互</li></ol><h2 id="核心系统" tabindex="-1">核心系统 <a class="header-anchor" href="#核心系统" aria-label="Permalink to &quot;核心系统&quot;">​</a></h2><h3 id="widget-体系" tabindex="-1">Widget 体系 <a class="header-anchor" href="#widget-体系" aria-label="Permalink to &quot;Widget 体系&quot;">​</a></h3><ul><li><strong>注册机制</strong>：<code>registerWidget</code> / <code>createWidgetPlugin</code> 注册式扩展</li><li><strong>Schema 工厂</strong>：<code>create(id)</code> 生成初始 Schema</li><li><strong>运行时组件</strong>：<code>WidgetRenderer</code> 根据 Schema 渲染组件</li><li><strong>属性面板</strong>：根据 Widget 配置自动生成属性编辑 UI</li></ul><h3 id="画布系统" tabindex="-1">画布系统 <a class="header-anchor" href="#画布系统" aria-label="Permalink to &quot;画布系统&quot;">​</a></h3><ul><li><strong>双布局模式</strong>：<code>free</code>（绝对定位，大屏）/ <code>flex</code>（流式，表单页）</li><li><strong>拖拽排序</strong>：拖拽创建、移动、调整大小</li><li><strong>对齐辅助</strong>：智能对齐线、网格吸附</li><li><strong>缩放平移</strong>：画布缩放、平移、适配屏幕</li></ul><h3 id="store-设计" tabindex="-1">Store 设计 <a class="header-anchor" href="#store-设计" aria-label="Permalink to &quot;Store 设计&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Store</th><th>职责</th></tr></thead><tbody><tr><td><code>widgetStore</code></td><td>Widget 数据真源、Schema CRUD</td></tr><tr><td><code>editorStore</code></td><td>交互状态、选择、immer 历史</td></tr><tr><td><code>boardStore</code></td><td>画布状态、缩放、平移</td></tr><tr><td><code>apiStore</code></td><td>持久化、保存、加载</td></tr><tr><td><code>eventStore</code></td><td>事件绑定、联动规则</td></tr><tr><td><code>variableStore</code></td><td>变量定义、表达式</td></tr></tbody></table><h3 id="事件引擎" tabindex="-1">事件引擎 <a class="header-anchor" href="#事件引擎" aria-label="Permalink to &quot;事件引擎&quot;">​</a></h3><ul><li><strong>事件类型</strong>：click、change、submit、validate 等</li><li><strong>联动规则</strong>：Widget 间联动、条件显隐、数据传递</li><li><strong>校验规则</strong>：必填、格式、范围、自定义校验</li></ul><h2 id="页面地图" tabindex="-1">页面地图 <a class="header-anchor" href="#页面地图" aria-label="Permalink to &quot;页面地图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AppLayout (侧栏，嵌入时隐藏)</span></span>
<span class="line"><span>├── /instances          InstancesView      实例列表（含大屏 Demo 预设）</span></span>
<span class="line"><span>├── /templates          WidgetTemplateView 部件模板库</span></span>
<span class="line"><span>├── /credentials        CredentialListView API 凭证</span></span>
<span class="line"><span>├── /tenants            TenantListView     租户管理</span></span>
<span class="line"><span>├── /key-usage          KeyUsageAuditView  密钥用量</span></span>
<span class="line"><span>├── /submissions        SubmissionListView 提交记录</span></span>
<span class="line"><span>├── /widget-docs        WidgetDocsView     部件文档</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── /editor?id=         EditorView         全屏设计器（视口剔除 / 4 模式）</span></span>
<span class="line"><span>├── /preview?id=        PreviewRenderView  草稿预览</span></span>
<span class="line"><span>└── /view/:code         PublishView        已发布运行时</span></span></code></pre></div><h2 id="设计态-vs-运行态" tabindex="-1">设计态 vs 运行态 <a class="header-anchor" href="#设计态-vs-运行态" aria-label="Permalink to &quot;设计态 vs 运行态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>设计态（Editor）</th><th>运行态（Runtime）</th></tr></thead><tbody><tr><td>组件</td><td>WidgetEditor</td><td>WidgetRenderer</td></tr><tr><td>数据</td><td>mock 数据 / 真实数据</td><td>真实数据</td></tr><tr><td>交互</td><td>拖拽、选择、配置</td><td>填写、提交</td></tr><tr><td>校验</td><td>实时校验（可关闭）</td><td>提交时校验</td></tr><tr><td>事件</td><td>设计态事件（预览）</td><td>运行态事件（执行）</td></tr></tbody></table><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="/schema-platform/docs/editor/widgets.html">Widget 体系</a></td><td>Widget 架构、注册机制</td></tr><tr><td><a href="/schema-platform/docs/editor/widget-development.html">Widget 开发指南</a></td><td>内置 Widget 开发规范</td></tr><tr><td><a href="/schema-platform/docs/editor/third-party-widget-guide.html">第三方 Widget</a></td><td>外部 Widget 扩展</td></tr><tr><td><a href="/schema-platform/docs/editor/canvas-system.html">双画布系统</a></td><td>画布架构、布局模式</td></tr><tr><td><a href="/schema-platform/docs/editor/config-systems.html">四大配置系统</a></td><td>配置系统设计</td></tr><tr><td><a href="/schema-platform/docs/editor/property-panel.html">属性面板</a></td><td>Widget 属性配置 UI</td></tr><tr><td><a href="/schema-platform/docs/editor/store-design.html">Store 设计</a></td><td>Widget 数据存储</td></tr></tbody></table>`,22)])])}const m=e(i,[["render",o]]);export{g as __pageData,m as default};
